from collections import defaultdict, deque

def solve(n, edges, s, t):
    if s == t:
        return 0
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
    q = deque([(s, [], 0)])
    visited = set()
    while q:
        node, path, weight = q.popleft()
        if node not in visited:
            visited.add(node)
            if node == t:
                return weight
            for neighbor, edge_weight in graph[node]:
                q.append((neighbor, path + [(node, neighbor, edge_weight)], weight + edge_weight))
    return -1

