def bellman_ford(n, edges, s, t):
    dist = [float('inf')] * n
    dist[s] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            return -1
    return dist[t] if dist[t] != float('inf') else -1

def solve(n, edges, s, t):
    if s == t:
        return 0
    return bellman_ford(n, edges, s, t)

