def solve(n, edges, s, t):
    if s == t:
        return 0
    graph = {i: {} for i in range(n)}
    for u, v, w in edges:
        graph[u][v] = w
    dist = {i: float('inf') for i in range(n)}
    dist[s] = 0
    queue = []
    heapq.heappush(queue, (0, s))
    while queue:
        du, u = heapq.heappop(queue)
        if u == t:
            break
        for v, w in graph[u].items():
            dv = du + w
            if dv < dist[v]:
