from queue import PriorityQueue

def solve(n, edges, s, t):
    pQ = PriorityQueue()
    pQ.put((0, s))
    explore = set()
    while not pQ.empty():
        w, now = pQ.get()
        if now == t:
            return w
        if now not in explore:
            explore.add(now)
            for child, dist in edges.get(now, []):
                pQ.put((w + dist, child))
    return -1

