class ShortestPathFinder:

    def __call__(self, n, edges, s, t):
        graph = self.construct_graph(edges, n)
        self.floyd_warshall(graph, n)
        if graph[s][t] != float('inf'):
            return graph[s][t]
        return -1

    def construct_graph(self, edges, n):
        import numpy as np
        graph = np.full((n, n), float('inf'))
        np.fill_diagonal(graph, 0)
        for u, v, w in edges:
            graph[u][v] = w
        return graph

    def floyd_warshall(self, graph, n):
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if graph[i][j] > graph[i][k] + graph[k][j]:
                        graph[i][j] = graph[i][k] + graph[k][j]

