class PathManager:

    def __init__(self, grid, start, goal):
        self.grid = grid
        self.start = start
        self.goal = goal
        self.open_set = [start]
        self.closed_set = []
        self.parent_map = {}

    def is_within_bounds(self, pos):
        rows, cols = (len(self.grid), len(self.grid[0]))
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_valid_move(self, pos):
        return self.is_within_bounds(pos) and self.grid[pos[0]][pos[1]] == '.'

    def get_neighbors(self, pos):
        r, c = pos
        neighbors = [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]
        return [n for n in neighbors if self.is_valid_move(n)]

    def reconstruct_path(self, current):
        path = []
        while current != self.start:
            path.append(current)
            current = self.parent_map[current]
        path.append(self.start)
        path.reverse()
        return path

    def solve(self):
        while self.open_set:
            current = self.open_set[0]
            for neighbor in self.get_neighbors(current):
                if neighbor == self.goal:
                    return self.reconstruct_path(neighbor)
                self.parent_map[neighbor] = current
                self.open_set.append(neighbor)
                time.sleep(1)
            self.open_set.remove(current)
            self.closed_set.append(current)
        return []

