    graph = {}
    for r, row in enumerate(grid):
        for c, col in enumerate(row):
            if col != '#':
                neighbors = []
                if r > 0:
                    neighbors.append((r - 1, c))
                if r < len(grid) - 1:
                    neighbors.append((r + 1, c))
                if c > 0:
                    neighbors.append((r, c - 1))
                if c < len(row) - 1:
                    neighbors.append((r, c + 1))
                graph[r, c] = neighbors
    return Graph(graph, heuristic(start, goal))

