class Graph:

    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v):
        self.adj[u].append(v)

    def is_cyclic(self):
        vis, path_vis = ([False] * self.n, [False] * self.n)
        for i in range(self.n):
            if not vis[i]:
                if self.dfs(i, vis, path_vis):
                    return True
        return False

    def dfs(self, u, vis, path_vis):
        vis[u] = True
        path_vis[u] = True
        for v in self.adj[u]:
            if not vis[v]:
                if self.dfs(v, vis, path_vis):
                    return True
            elif path_vis[v]:
                return True
        path_vis[u] = False
        return False

def solve(n, prerequisites):
    graph = Graph(n)
    for b, a in prerequisites:
        graph.add_edge(a, b)
    if graph.is_cyclic():
        return []
    order = []
    vis = [False] * n

    def dfs(u):
        vis[u] = True
        for v in graph.adj[u]:
            if not vis[v]:
                dfs(v)
        order.append(u)
        graph.adj[u].clear()
    for i in range(n):
        if not vis[i]:
            dfs(i)
    return order[::-1]

