        low, high = (0, len(nums))
        while low < high:
            mid = (low + high) // 2
            if nums[mid] < target:
                low = mid + 1
            else:
                high = mid
        return low if low < len(nums) and nums[low] == target else -1

    def right_most(nums, target):
        low, high = (0, len(nums))
        while low < high:
            mid = (low + high) // 2
            if nums[mid] <= target:
                low = mid + 1
            else:
                high = mid
        return low - 1 if low > 0 and nums[low - 1] == target else -1
    first = left_most(nums, target)
    last = right_most(nums, target)
    return [first, last]

def solve(nums, target):

    def binary_search(nums, target, left, right, find_left):
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left if not find_left else right
    first = binary_search(nums, target, 0, len(nums) - 1, True)
    last = binary_search(nums, target, 0, len(nums) - 1, False)
    if first <= last and first < len(nums) and (nums[first] == target):
        return [first, last]
    else:
        return [-1, -1]

def solve(nums, target):

    def binary_search_left(nums, target):
        left, right = (0, len(nums) - 1)
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] >= target:
                right = mid - 1
            else:
                left = mid + 1
        return left
    left_index = binary_search_left(nums, target)
    if left_index == len(nums) or nums[left_index] != target:
        return [-1, -1]
    binary_search_right = lambda nums, target: binary_search_left(nums, target + 1)
    right_index = binary_search_right(nums, target)
    return [left_index, right_index - 1]

