def compute_path_cost(coming_from, end, g):
    tot = 0
    pointer = end
    while pointer != g:
        tot += coming_from[pointer]
        v, w, u = next(((v, w, u) for v, w, u in edges if u == pointer))
        del coming_from[u]
        pointer = v
    del coming_from[pointer]
    return tot

