def solve(n, edges):
    """Returns the number of connected components of an undirected graph."""
    parent = [i for i in range(n)]
    ranks = [1] * n

    def find(node):
        if node != parent[node]:
            parent[node] = find(parent[node])
        return parent[node]

    def union(i, j):
        u = find(i)
        v = find(j)
        if u == v:
            return False
        elif ranks[u] > ranks[v]:
            ranks[u] += ranks[v]
            parent[v] = u
        else:
            ranks[v] += ranks[u]
            parent[u] = v
        return True
    for i, j in edges:
        union(i, j)
    components = set()
    for i in range(n):
        components.add(find(i))
    return len(components)

