def solve(n, edges):
    """Returns the number of connected components of an undirected graph.
    """
    edges = list(edges)
    if len(edges) == 0:
        return n
    edges = list(map(lambda x: set(x), edges))
    nodes = n
    result = 0
    to_traverse = [set(edges[0])]
    while len(to_traverse) > 0:
        actual = to_traverse.pop()
        result += 1
        nodes -= len(actual)
        to_append = set()
        for id in actual:
            for edge in edges:
                if id in edge:
                    temp_edge = edge
                    while id in temp_edge:
                        temp_edge.remove(id)
                    temp_edge = set(temp_edge)
                    if temp_edge.issubset(actual):
                        continue
                    to_append.add(temp_edge)
        if to_append == set():
            continue
        to_traverse += list(to_append)
    return min(result, nodes)

