    ints = intervals
    nums = sorted((l for l in list(itertools.chain(*ints))))
    groups = set()
    for num in nums:
        gs = set()
        for g in groups:
            if g[0] < num < g[-1]:
                break
            elif num in g:
                gs.add(g)
                continue
            lg = g[:]
            if lg[0] <= num < lg[1]:
                lg[-1] = max(lg[-1], num)
                gs.add(tuple(lg))
            elif lg[0] > num:
                lg[0] = min(lg[0], num)
                gs.add(tuple(lg))
            else:
                gs.add(g)
        groups = gs | {tuple([num])}
    return [list(g) for g in sorted(groups)]

