def maxInterval(intervals):
    """Return intervals count.
    """
    intervals.sort(key=lambda x: x[1])
    endpoints = []
    for i in intervals:
        endpoints.append(i[1])
    length_endpoints = len(endpoints)
    count = 0
    index = [0]
    for j in range(1, length_endpoints):
        if endpoints[index[-1]] < endpoints[j]:
            count += 1
            index.append(j)
    return count + 1

