def solve(n, prerequisites):
    """[summary]

    Args:
        n ([type]): [number of tasks]
        prerequisites ([type]): [sequency of pairs, each indicates the order in which tasks have to be excecuted]

    Returns:
        [list]: [Valid sequency of tasks in a list]
    """
    from collections import deque
    G = {i: set() for i in range(n)}
    i_g = {i: set() for i in range(n)}
    for u, v in prerequisites:
        G[v].add(u)
        i_g[u].add(v)
    q = deque([i for i in range(n) if i not in i_g])
    seen = set()
    ans = []
    while q:
        u = q.popleft()
        seen.add(u)
        ans.append(G.pop(u))
        for v in G:
            if u in G[v]:
                G[v].discard(u)
                if v not in i_g:
                    q.appendleft(v)
    if len(G) > 0:
        return []
    if len(seen) == n:
        return ans
    return []

