    for edge in edges:
        adj_list[edge[0]].append(edge[1])
        adj_list[edge[1]].append(edge[0])
    visited = [False] * n
    rec_stack = [False] * n

    def is_cyclic_util(v, visited, rec_stack):
        visited[v] = True
        rec_stack[v] = True
        for neighbor in adj_list[v]:
            if not visited[neighbor]:
                if is_cyclic_util(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True
        rec_stack[v] = False
        return False
    for i in range(n):
        if not visited[i]:
            if is_cyclic_util(i, visited, rec_stack):
                return True
    return False

