def solve(n, edges):
    """ Take the inputs of a graph (nodes + edges) and return a value indicating whether it's cyclic or not. """
    cost = 0
    cycle = False
    costs = {node: -1 for node in range(n)}
    for start_node, end_node in edges:
        if costs[start_node] == -1:
            costs[start_node] = cost
            cost += 1
        if costs[end_node] == costs[start_node]:
            cycle = True
        if costs[end_node] == -1:
            costs[end_node] = costs[start_node]
    start_node = next((node for node in costs if costs[node] != -1))
    end_node = costs[start_node]
    while end_node < cost - 2:
        possible_nodes = [node for node in range(n) if costs[node] == end_node]
        for node in possible_nodes:
            for adjacent_node in possible_nodes:
                if node != adjacent_node and node not in [start_node, end_node + 1] and (adjacent_node not in [start_node, end_node + 1]):
                    costs[node] == end_node + 1
                    cycle = True
                    return cycle
        end_node = next((node for node in range(end_node + 2, cost - 2) if node in costs))
    return cycle

