def solve(n, edges):
    """ Find whether a cycle exists in list of undirected edages. """

    def find(ancestor, vertex):
        """ Trace back find the root given a vertex. """
        if ancestor[vertex] == vertex:
            return vertex
        furthest = find(ancestor, ancestor[vertex])
        ancestor[vertex] = furthest
        return furthest

    def union(ancestor, vertex, edge):
        """ Link the ancestor of the two. """
        b = find(ancestor, vertex)
        e = find(ancestor, edge)
        if b != e:
            ancestor[b] = e
    parents = range(n)
    for vertex, edge in edges:
        b = find(parents, vertex)
        e = find(parents, edge)
        if b == e:
            return True
        union(parents, vertex, edge)
    return False

