def solve(n, edges):
    """
    Returns True if an undirected graph contains a cycle using a union-find data structure.

    Args:
    n (int): The number of nodes in the graph.
    edges (list of list of int): A list of pairs [u, v] representing the edges in the graph.

    Returns:
    bool: True if the graph contains a cycle, False otherwise.
    """

    class Tree:

        def __init__(self, label):
            self.label = label
            self.parent = self
            self.rank = 0

    def union(t1, t2):
        if t1.rank > t2.rank:
            t2.parent = t1
        else:
            t1.parent = t2
            if t2.rank == t1.rank:
                t2.rank += 1

    def find(t):
        if t.parent.label != t.label:
            t.parent = find(t.parent)
        return t.parent
    trees = [Tree(label=label) for label in range(n)]
    for u, v in edges:
        root_u = find(trees[u])
        root_v = find(trees[v])
        if root_u == root_v:
            return True
        else:
            union(root_u, root_v)
    return False

