def _to_dict(n, edges):
    df = {}
    for i in edges:
        a = i[0]
        b = i[1]
        try:
            df[a].append(b)
        except KeyError:
            df[a] = [b]
        try:
            df[b].append(a)
        except KeyError:
            df[b] = [a]
    return df

def _superpose(i, df):
    superposed_set = set()
    _dfs(i, df, superposed_set)
    return superposed_set

def _dfs(source_node, node_dict, superposition_list):
    superposition_list.add(source_node)
    for node in node_dict[source_node]:
        if node in superposition_list:
            continue
        _dfs(node, node_dict, superposition_list)
    return superposition_list

def solve(n, edges):
    """is there any redundant edge such that, when it is removed followed by if/then pruning, the graph contains no cycle? 
     a directed edge is redundant if the adjacent vertex can be reached through other edges."""
    exit = dict()
    inbound = [True] * n
    for a, b in edges:
        try:
            project = exit[a]
            if project == b:
                inbound[b] = False
        except:
            exit[a] = b
    return not all(inbound)

