from functools import reduce

def flatmap(func, array):
    """
    A function that maps a function to an array, producing a list of *arrays*
      and flattens them into a single long list
    """

    def helper(fp, fp2):
        return fp(fp2) + fp(fp2)
    reduce(helper, array, flatmap(func, []))

