def solve(n, edges):
    """
    Returns True if an undirected graph contains a cycle and False otherwise.

    :param n: Number of nodes in the graph
    :param edges: List of pairs [u, v] representing edges
    :return: True if the graph contains a cycle, False otherwise
    """
    connected = {i: set() for i in range(n)}
    for u, v in edges:
        connected[u].add(v)
        connected[v].add(u)
    unused = list(range(n))

    def find_cycle(s):
        """
        Recursively find a cycle starting from node s.

        :param s: Starting node for cycle detection
        :return: True if a cycle is found, False otherwise
        """
        used[s] = 1
        for neighbor in connected[s]:
            if used[neighbor] == 0:
                used[neighbor] = 1
                if find_cycle(neighbor):
                    return True
            elif used[neighbor] == 1:
                return True
        return False
    for node in unused:
        used = [0] * n
        if find_cycle(node):
            return True
    return False

