class UnionFind:

    def __init__(self, n):
        self.root = list(range(n))
        self.size = [1] * n
        self.count = n

    def find(self, x):
        """查找元素 x 所属的集合，同时进行路径压缩"""
        if self.root[x] != x:
            self.root[x] = self.find(self.root[x])
        return self.root[x]

    def union(self, x, y):
        """将元素 x 和 y 所属的两个集合合并"""
        rx, ry = (self.find(x), self.find(y))
        if rx == ry:
            return False
        if self.size[rx] < self.size[ry]:
            rx, ry = (ry, rx)
        self.root[ry] = rx
        self.size[rx] += self.size[ry]
        self.count -= 1
        return True

    def get_count(self):
        """返回当前图中的连通分量数目"""
        return self.count

