def heapsort(arr, arrSize, i):
    largest = i
    l = 2 * i + 1
    r = 2 * i + 2
    if l < arrSize and arr[l] > arr[largest]:
        largest = l
    if r < arrSize and arr[r] > arr[largest]:
        largest = r
    if largest != i:
        arr[i], arr[largest] = (arr[largest], arr[i])
        heapsort(arr, arrSize, largest)

