def maximize_conveyor_belt_similarity(belt1, belt2):
    if not belt1 or not belt2:
        return 0
    n, m = (len(belt1), len(belt2))
    pos_dict = {train: idx for idx, train in enumerate(belt2)}
    max_similarity = 0
    for i in range(n - m + 1):
        similarity = 0
        for j in range(m):
            if belt1[i + j] == belt2[j]:
                similarity += 1
            else:
                train_to_move = belt1[i + j]
                if train_to_move in pos_dict:
                    swap_pos = pos_dict[train_to_move]
                    belt1[i + j], belt1[swap_pos] = (belt1[swap_pos], belt1[i + j])
                    similarity += 1
        max_similarity = max(max_similarity, similarity)
    return max_similarity

def solve_conveyor_belt_one_point(belt1_size, belt2_size, differences):

    def hamiltonian_circuit(belt2, differences):
        visited = [False] * len(belt2)
        used_pairs = set()

        def dfs(curr, visited, used_pairs, count):
            if count == len(belt2):
                return True
            for j in range(len(belt2)):
                if not visited[j] and (curr, j) not in used_pairs:
                    used_pairs.add((curr, j))
                    visited[j] = True
                    if dfs(j, visited, used_pairs, count + 1):
                        return True
                    visited[j] = False
                    used_pairs.remove((curr, j))
            return False
        for i in range(len(belt2)):
            if not visited[i] and dfs(i, visited, used_pairs, 1):
                return True
        return False
    return hamiltonian_circuit(differences, differences)

