        if len(arr) == 1:
            return arr[0]
        pivot_index = partition(arr, 0, len(arr) - 1)
        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(arr[:pivot_index], k)
        else:
