def solve(n, edges):
    # Initialize visited list to keep track of visited nodes
    visited = [False] * n

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # DFS to traverse the graph and mark visited nodes
    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    # Count connected components
    count = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1

    return count

