    first, last = -1, -1

    # Find the first occurrence
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    if left < len(nums) and nums[left] == target:
        first = left

    # Find the last occurrence
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] > target:
            right = mid - 1
        else:
            left = mid + 1
    if right >= 0 and nums[right] == target:
        last = right

    return [first, last]

