def solve(n, edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    parent = [-1] * n

    def has_cycle(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                if has_cycle(neighbor):
                    return True
            elif parent[node] != neighbor:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if has_cycle(i):
                return True
    return False

def solve(n, edges):
    def dfs(node, visited, recursion_stack):
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                if dfs(neighbor, visited, recursion_stack):
                    return True
            elif neighbor in recursion_stack:
                return True
        recursion_stack.remove(node)
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
    for i in range(n):
        if i not in visited:
            if dfs(i, visited, set()):
                return True
    return False

